#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 long long minOperations(vector<int>& nums1,vector<int>& nums2,int k){
  long long pos=0,neg=0;
  for(int i=0;i<(int)nums1.size();++i){long long d=(long long)nums1[i]-nums2[i];
   if(k==0){if(d)return -1;continue;}
   if(d%k)return -1;
   if(d>0)pos+=d/k;else neg-=d/k;
  }
  return pos==neg?pos:-1;
 }
};
